package gen

import (
	"bytes"
	"fmt"
	"go/format"
	"strings"

	"github.com/mickamy/standin/internal/infer"
)

// FileName is the name of the generated file inside the destination
// directory.
const FileName = "fixture_gen.go"

// GofakeitImport is the import path of the faker used by generated code.
const GofakeitImport = "github.com/brianvoe/gofakeit/v7"

// Params describes one generation run.
type Params struct {
	// PackageName is the package name of the generated file.
	PackageName string
	// SourceName is the source package name, used as the type qualifier.
	SourceName string
	// SourcePath is the source package import path.
	SourcePath string
	// Fixtures holds the fixture bodies in output order.
	Fixtures []infer.Fixture
}

// File renders the generated fixture file, formatted with go/format. The
// output is deterministic: the same params produce byte-identical output.
func File(p Params) ([]byte, error) {
	var buf bytes.Buffer

	buf.WriteString("// Code generated by standin. DO NOT EDIT.\n\n")
	buf.WriteString("package " + p.PackageName + "\n")

	if len(p.Fixtures) > 0 {
		writeImports(&buf, p)
	}

	for _, fx := range p.Fixtures {
		writeFixture(&buf, p.SourceName, fx)
	}

	src, err := format.Source(buf.Bytes())
	if err != nil {
		return nil, fmt.Errorf("format generated code: %w", err)
	}

	return src, nil
}

func writeImports(buf *bytes.Buffer, p Params) {
	buf.WriteString("\nimport (\n")

	if needsGofakeit(p.Fixtures) {
		fmt.Fprintf(buf, "\t%q\n\n", GofakeitImport)
	}

	fmt.Fprintf(buf, "\t%q\n)\n", p.SourcePath)
}

func needsGofakeit(fixtures []infer.Fixture) bool {
	for _, fx := range fixtures {
		for _, f := range fx.Fields {
			if strings.Contains(f.Expr, "gofakeit.") {
				return true
			}
		}
	}

	return false
}

func writeFixture(buf *bytes.Buffer, qualifier string, fx infer.Fixture) {
	typ := qualifier + "." + fx.Name

	fmt.Fprintf(buf, "\nfunc %s(setters ...func(m *%s)) %s {\n", fx.Name, typ, typ)

	if len(fx.Fields) == 0 {
		fmt.Fprintf(buf, "\tm := %s{}\n", typ)
	} else {
		fmt.Fprintf(buf, "\tm := %s{\n", typ)

		for _, f := range fx.Fields {
			fmt.Fprintf(buf, "\t\t%s: %s,\n", f.Name, f.Expr)
		}

		buf.WriteString("\t}\n")
	}

	buf.WriteString("\tfor _, s := range setters {\n\t\ts(&m)\n\t}\n\treturn m\n}\n")
}
